═══════════ FILE: footerConfig.js ═══════════
/** @type {import('../buildTemplate').ContentTypeDefinition} */
module.exports = {
  id: 'footerConfig',
  name: 'Footer Config',
  displayField: 'internalTitle',
  description:
    'Root footer entry. One default (unscoped) entry per locale, optionally overridden ' +
    'by additional entries scoped via `regions` to specific SFCC sites — see the ' +
    'region-resolution utility for precedence rules.',
  fields: [
    { id: 'internalTitle', name: 'Internal Title', type: 'Symbol', required: true, localized: false },
    { id: 'subscribeHeading', name: 'Subscribe Heading', type: 'Symbol', required: false, localized: true },
    { id: 'subscribeBody', name: 'Subscribe Body', type: 'Symbol', required: false, localized: true },
    {
      id: 'navGroups',
      name: 'Nav Groups',
      type: 'Array',
      required: true,
      localized: false,
      items: { type: 'Link', linkType: 'Entry', validations: [{ linkContentType: ['navGroup'] }] },
    },
    {
      id: 'legalLinks',
      name: 'Legal Links',
      type: 'Array',
      required: false,
      localized: false,
      items: { type: 'Link', linkType: 'Entry', validations: [{ linkContentType: ['link'] }] },
    },
    { id: 'copyrightOwner', name: 'Copyright Owner', type: 'Symbol', required: false, localized: false },
    // Contact channels rendered by ContactIconRow. Optional: a storefront without a
    // channel renders that icon non-interactive rather than hiding the row. Values are
    // passed through isSafeHref before reaching an anchor, so an editor cannot introduce
    // a javascript:/data: URL from the CMS. Each channel's accessible-name label is
    // co-located here with its own href rather than living as a generic uiCopy string —
    // an editor changing a channel's destination is the same edit as changing its label,
    // and ContactIconRow already falls back to its own default label when unset, so an
    // existing entry with no label field yet degrades gracefully rather than breaking.
    { id: 'phoneHref', name: 'Phone Href', type: 'Symbol', required: false, localized: false },
    { id: 'phoneLabel', name: 'Phone Label', type: 'Symbol', required: false, localized: true },
    { id: 'whatsAppHref', name: 'WhatsApp Href', type: 'Symbol', required: false, localized: false },
    { id: 'whatsAppLabel', name: 'WhatsApp Label', type: 'Symbol', required: false, localized: true },
    { id: 'emailHref', name: 'Email Href', type: 'Symbol', required: false, localized: false },
    { id: 'emailLabel', name: 'Email Label', type: 'Symbol', required: false, localized: true },
    {
      id: 'regions',
      name: 'Regions',
      type: 'Array',
      required: false,
      localized: false,
      // Omitted/empty = the default/global footer for its locale. A narrower-scoped
      // entry (e.g. regions: [ZimmermannUS]) takes precedence over this one when
      // resolving which footerConfig to render for a given site.
      items: { type: 'Link', linkType: 'Entry', validations: [{ linkContentType: ['region'] }] },
    },
  ],
};

═══════════ FILE: headerNavItem.js ═══════════
const { TOGGLE_APPEARANCE_APP_DEFINITION_ID } = require('../appIds');

/** @type {import('../buildTemplate').ContentTypeDefinition} */
module.exports = {
  id: 'headerNavItem',
  name: 'Header Nav Item',
  displayField: 'label',
  description:
    'A single top-level entry in the global header navigation — either a direct link ' +
    '(href set, no columns) or a mega-menu trigger (one or more columns of navGroup ' +
    'references, no href). Referenced (ordered) from headerNavigation.',
  editorInterface: {
    controls: [
      {
        fieldId: 'twoColumnLayout',
        widgetId: TOGGLE_APPEARANCE_APP_DEFINITION_ID,
        widgetNamespace: 'app',
      },
    ],
  },
  fields: [
    { id: 'label', name: 'Label', type: 'Symbol', required: true, localized: true },
    // Set only for a direct-link item (e.g. a "Z.Immerse" entry) with no dropdown. CMA has
    // no way to enforce this structurally — same documented-not-enforced caveat as
    // link.js's free-text href field: exactly one of `href` or a non-empty `columns` should
    // be set on any given item, never both, never neither.
    { id: 'href', name: 'URL', type: 'Symbol', required: false, localized: false },
    // Mega-menu columns. 0 columns = direct link via `href` above; 1+ = mega-menu.
    // `navGroup` is authored on a separate branch (feature/contentful-navgroup-migration)
    // and has no local file in this content-types/ directory yet — referenced here by
    // content-type-ID string only, the same way footerConfig.js references 'footerNavGroup'.
    {
      id: 'columns',
      name: 'Columns',
      type: 'Array',
      required: false,
      localized: false,
      items: { type: 'Link', linkType: 'Entry', validations: [{ linkContentType: ['navGroup'] }] },
    },
    // Desktop/tablet only — default stacks every `columns` group in one shared column. Set
    // true for an item with multiple distinct headed sections that should sit side by side
    // (e.g. "Collections"). Explicit editorial flag rather than inferring from content shape.
    {
      id: 'twoColumnLayout',
      name: 'Two Column Layout',
      type: 'Boolean',
      required: false,
      localized: false,
    },
    // Links the reusable `image` primitive (asset + altText/decorative/caption/link) rather
    // than a raw Asset directly — lets an editor set real accessible alt text per usage instead
    // of falling back to the asset's own title/description. Re-added under the same field id
    // after a two-step migration: Contentful field types are immutable in place, so changing
    // linkType Asset -> Entry required omitting, deleting, then re-adding this field (see git
    // history) — the id itself never changed, so no app-code field-name churn.
    {
      id: 'promoImage',
      name: 'Promo Image',
      type: 'Link',
      linkType: 'Entry',
      required: false,
      localized: false,
      validations: [{ linkContentType: ['image'] }],
    },
    {
      id: 'regions',
      name: 'Regions',
      type: 'Array',
      required: false,
      localized: false,
      // Omitted/empty = applies to all regions (the default/global case) — per-item market
      // scoping, same pattern as link.js/footerConfig.js's regions field.
      items: { type: 'Link', linkType: 'Entry', validations: [{ linkContentType: ['region'] }] },
    },
  ],
};

