/** @type {import('../buildTemplate').ContentTypeDefinition} */
module.exports = {
  id: 'iconAndText',
  name: 'Icon and Text',
  description:
    'Displays a collection of icon and text tiles in configurable layouts (2, 3, 4 horizontal or vertical). Each tile contains an icon, heading, and optional description. Content is managed independently per storefront in Contentful.',
  displayField: 'internalTitle',
  editorInterface: {
    controls: [
      { fieldId: 'internalTitle', widgetId: 'singleLine', widgetNamespace: 'builtin' },
      { fieldId: 'placement', widgetId: 'dropdown', widgetNamespace: 'builtin' },
      { fieldId: 'layout', widgetId: 'dropdown', widgetNamespace: 'builtin' },
      { fieldId: 'sectionTitle', widgetId: 'singleLine', widgetNamespace: 'builtin' },
      { fieldId: 'items', widgetId: 'entryLinksEditor', widgetNamespace: 'builtin' },
    ],
  },
  fields: [
    // Editor-facing label only — not rendered. displayField so it shows in the entry list.
    { id: 'internalTitle', name: 'Internal Title', type: 'Symbol', required: false, localized: false },
    // Stable identifier used to fetch a specific entry by placement rather than relying on
    // response ordering (entries[0] is non-deterministic when multiple entries exist).
    // Optional for backward compatibility with entries authored before this field was added.
    {
      id: 'placement',
      name: 'Placement',
      type: 'Symbol',
      required: false,
      localized: false,
      validations: [{ in: ['benefits'] }, { unique: true }],
    },
    {
      id: 'layout',
      name: 'Layout',
      type: 'Symbol',
      required: false,
      localized: false,
      validations: [{ in: ['2 Column', '3 Column', '4 Column', 'Vertical'] }],
    },
    // Optional heading displayed above the tile grid. Localized so each storefront can author
    // its own copy (e.g. "ZIMMERMANN BENEFITS" in AU-English vs a translated equivalent).
    { id: 'sectionTitle', name: 'Section Title', type: 'Symbol', required: false, localized: true },
    {
      id: 'items',
      name: 'Items',
      type: 'Array',
      required: false,
      localized: false,
      validations: [{ size: { min: 2, max: 4 } }],
      items: {
        type: 'Link',
        linkType: 'Entry',
        validations: [{ linkContentType: ['iconAndTextItem'] }],
      },
    },
  ],
};

