/** @type {import('../buildTemplate').ContentTypeDefinition} */
module.exports = {
  id: 'navGroup',
  name: 'Nav Group',
  displayField: 'internalTitle',
  description:
    'A reusable "heading + list of links" column — generalised from footerNavGroup so both ' +
    'the footer and the header mega-menu can reference the same shape. `heading` is optional ' +
    '(omitted means an unheaded group); `showContactChannels` is a footer-only flag that a ' +
