    // localised, so matching its text breaks per storefront. Footer-only; harmlessly unused
    // by header mega-menu groups.
    {
      id: 'showContactChannels',
      name: 'Show Contact Channels',
      type: 'Boolean',
      required: false,
      localized: false,
