#!/usr/bin/env node
/**
 * Build (or update) the Zimmermann content model as a single, organization-scoped
 * Contentful Environment Template — the mechanism Contentful now expects content
 * models to be authored through, replacing the old per-environment sync.js +
 * migrations/*.mjs pipeline (see scripts/contentful/README.md).
 *
 * Every file in ./content-types/ defines one content type; this script assembles all
 * of them into one EnvironmentTemplate's `entities.contentTypeTemplates`, get-or-creates
 * it by name under CONTENTFUL_ORGANIZATION_ID, and bumps its version. The template
 * itself does not touch any space or environment — see setup/installTemplate.mjs for
 * pushing it into one.
 *
 * Usage:
 *   npm run sync:contentful
 *   npm run sync:contentful -- --version-name "add region/link/footer/uiCopy models"
 */

'use strict';

const contentfulManagement = require('contentful-management');
const path = require('path');
const fs = require('fs');

/**
 * @typedef {Object} FieldDefinition
 * @property {string} id
 * @property {string} name
 * @property {string} type
 * @property {string} [linkType]
 * @property {boolean} [required]
 * @property {boolean} [localized]
 * @property {boolean} [disabled]
 * @property {boolean} [omitted]
 * @property {Record<string, unknown>} [defaultValue]
 * @property {string} [helpText]
 * @property {import('contentful-management').ContentTypeFieldValidation[]} [validations]
 * @property {{type: string, linkType?: string, validations?: import('contentful-management').ContentTypeFieldValidation[]}} [items]
 */

/**
 * @typedef {Object} EditorInterfaceControl
 * @property {string} fieldId
 * @property {string} [widgetId]
 * @property {string} [widgetNamespace]
 * @property {import('contentful-management').DefinedParameters} [settings]
 */

/**
 * @typedef {Object} EditorInterfaceDefinition
 * @property {EditorInterfaceControl[]} [controls]
 */

/**
 * @typedef {Object} ContentTypeDefinition
 * @property {string} id
 * @property {string} name
 * @property {string} [displayField]
 * @property {string} [description]
 * @property {FieldDefinition[]} fields
 * @property {EditorInterfaceDefinition} [editorInterface]
 */

const REQUIRED_ENV = ['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_ORGANIZATION_ID'];

// The one EnvironmentTemplate this repo owns. Looked up by name (get-or-create) rather
// than a stored ID, matching the get-or-create idiom the rest of this pipeline already
// uses — no ID to keep in sync across machines/CI.
const TEMPLATE_NAME = 'Zimmermann Content Model';

function checkEnv() {
  const missing = REQUIRED_ENV.filter((k) => !process.env[k]);
  if (missing.length) {
    console.error(`\n❌  Missing env vars: ${missing.join(', ')}`);
    console.error('   Add them to .env (at repo root) and re-run.\n');
    process.exit(1);
  }
}

function getArg(flag) {
  const args = process.argv.slice(2);
  const i = args.indexOf(flag);
  return i !== -1 ? args[i + 1] : null;
}

/**
 * Build a Content Type Template field payload. Same shape as a plain content-type
 * field, `localized` just needs to be explicit now — there is no longer a migration
 * file layered on top to override an inferior default.
 * @param {FieldDefinition} def
 * @returns {import('contentful-management').ContentFields}
 */
function buildField(def) {
  /** @type {import('contentful-management').ContentFields} */
  const field = {
    id: def.id,
    name: def.name,
    type: def.type,
    required: def.required ?? false,
    localized: def.localized ?? false,
    validations: def.validations ?? [],
  };
  if (def.disabled != null) field.disabled = def.disabled;
  if (def.omitted != null) field.omitted = def.omitted;
  if (def.linkType) field.linkType = def.linkType;
  if (def.items) field.items = def.items;
  if (def.defaultValue) field.defaultValue = def.defaultValue;
  return field;
}

/**
 * @param {ContentTypeDefinition} def
 * @returns {import('contentful-management').ContentTypeTemplateProps}
 */
function buildContentTypeTemplate(def) {
  return {
    id: def.id,
    name: def.name,
    displayField: def.displayField,
    description: def.description ?? '',
    fields: def.fields.map(buildField),
  };
}

/**
 * Build an Editor Interface Template payload for one content type, if it defines one.
 * A content type without an `editorInterface` simply gets no entry — Contentful falls
 * back to its own default widget per field type, same as today's behaviour.
 * @param {ContentTypeDefinition} def
 * @returns {import('contentful-management').EditorInterfaceTemplateProps | null}
 */
function buildEditorInterfaceTemplate(def) {
  if (!def.editorInterface) return null;
  return {
    contentTypeTemplate: { sys: { type: 'Link', linkType: 'ContentTypeTemplate', id: def.id } },
    controls: def.editorInterface.controls,
  };
}

async function main() {
  checkEnv();

  const organizationId = process.env.CONTENTFUL_ORGANIZATION_ID;
  const versionName = getArg('--version-name') ?? new Date().toISOString();
  const versionDescription = getArg('--version-description') ?? undefined;

  const client = contentfulManagement.createClient(
    { accessToken: process.env.CONTENTFUL_MANAGEMENT_TOKEN },
    { type: 'plain' },
  );

  const defsDir = path.join(__dirname, 'content-types');
  const files = fs
    .readdirSync(defsDir)
    .filter((f) => f.endsWith('.js'))
    .sort();

  if (!files.length) {
    console.log('No content type definitions found in scripts/contentful/content-types/');
    return;
  }

  const defs = files.map((file) => {
    const def = /** @type {ContentTypeDefinition} */ (require(path.join(defsDir, file)));
    console.log(`→ Including "${def.id}" (${file})`);
    return def;
  });

  const contentTypeTemplates = defs.map(buildContentTypeTemplate);
  const editorInterfaceTemplates = defs.map(buildEditorInterfaceTemplate).filter(Boolean);

  const { items: existing } = await client.environmentTemplate.getMany({
    organizationId,
    query: { limit: 100 },
  });
  const found = existing.find((t) => t.name === TEMPLATE_NAME);

  if (!found) {
    await client.environmentTemplate.create(
      { organizationId },
      {
        name: TEMPLATE_NAME,
        description: 'Zimmermann PWA content model — every content type in one place, installed per environment.',
        versionName,
        versionDescription,
        entities: { contentTypeTemplates, editorInterfaceTemplates },
      },
    );
    console.log(`  ✅  Created EnvironmentTemplate "${TEMPLATE_NAME}"`);
    console.log('\n✅  Build complete.\n');
    return;
  }

  found.entities = { contentTypeTemplates, editorInterfaceTemplates };
  found.versionName = versionName;
  found.versionDescription = versionDescription;

  await client.environmentTemplate.update({ organizationId, environmentTemplateId: found.sys.id }, found);
  console.log(`  ♻️   Updated EnvironmentTemplate "${TEMPLATE_NAME}"`);
  console.log('\n✅  Build complete. Run `npm run install:contentful -- --target <env>` to push this out.\n');
}

main().catch((err) => {
  console.error('\n❌  Build failed:', err.message ?? err);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * Install (or update) the Zimmermann Environment Template into one target environment.
 *
 * Replaces the old runMigrations.mjs promotion flow. There is no more hand-rolled
 * '_migrationHistory' content type or detectDrift.mjs — Contentful tracks each
 * environment's install status/version natively via environmentTemplateInstallation,
 * and cross-environment content-type drift can't happen the way it used to since every
 * environment installs from the same versioned template.
 *
 * Usage:
 *   npm run sync:contentful                            # author the template first (buildTemplate.js)
 *   npm run install:contentful -- --target dev
 *   npm run install:contentful -- --target sit --dry-run
 *
 * If validation reports a content type that already exists in the target environment
 * but isn't managed by this template (e.g. one created by the old sync.js pipeline
 * before this template-based approach existed), the install is refused by Contentful.
 * Adopt it into the template explicitly rather than deleting it first:
 *   npm run install:contentful -- --target dev --takeover shoppableImage,otherType
 *
 * Promotion order: dev → test → sit → staging → uat → master (via production alias)
 */

import { checkEnv, createClient, log } from './_shared.mjs';

const args = process.argv.slice(2);
const getArg = (flag) => {
  const i = args.indexOf(flag);
  return i !== -1 ? args[i + 1] : null;
};

const TARGET = getArg('--target');
const DRY_RUN = args.includes('--dry-run');
const FORCE = args.includes('--force');
const DELETE_DELETED_FIELDS = args.includes('--delete-deleted-fields');
const TAKEOVER_IDS = (getArg('--takeover') ?? '')
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);

if (!TARGET) {
  log.error('--target <environmentId> is required.');
  console.error('  Example: npm run install:contentful -- --target dev\n');
  console.error('  Promotion order: dev → test → sit → staging → uat → master\n');
  process.exit(1);
}

// Must match TEMPLATE_NAME in ../buildTemplate.js — the template is looked up by name,
// not a stored ID, so the two files just need to agree on the literal.
const TEMPLATE_NAME = 'Zimmermann Content Model';

const TERMINAL_STATUSES = new Set(['succeeded', 'failed', 'disconnected']);

async function pollInstallation(
  client,
  { organizationId, spaceId, environmentId, environmentTemplateId },
  timeoutMs = 120_000,
) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const { items } = await client.environmentTemplateInstallation.getForEnvironment({
      spaceId,
      environmentId,
      environmentTemplateId,
      limit: 1,
    });
    const [latest] = items;
    if (latest && TERMINAL_STATUSES.has(latest.sys.status)) return latest;
    await new Promise((r) => setTimeout(r, 3_000));
    process.stdout.write('.');
  }
  throw new Error(`Installation into '${environmentId}' did not reach a terminal status within ${timeoutMs / 1000}s`);
}

async function main() {
  checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_ORGANIZATION_ID', 'CONTENTFUL_SPACE_ID']);

  const organizationId = process.env.CONTENTFUL_ORGANIZATION_ID;
  const spaceId = process.env.CONTENTFUL_SPACE_ID;

  const client = createClient();

  const { items: templates } = await client.environmentTemplate.getMany({ organizationId, query: { limit: 100 } });
  const template = templates.find((t) => t.name === TEMPLATE_NAME);

  if (!template) {
    log.error(`No EnvironmentTemplate named "${TEMPLATE_NAME}" found in organization '${organizationId}'.`);
    console.error('  Run `npm run build:contentful` first.\n');
    process.exit(1);
  }

  log.section(`Install → '${TARGET}'`);
  console.log(`  Template: "${TEMPLATE_NAME}" (version ${template.sys.version})`);

  log.info('Validating...');
  const validation = await client.environmentTemplate.validate(
    { spaceId, environmentId: TARGET, environmentTemplateId: template.sys.id, version: template.sys.version },
    {},
  );

  const conflictingIds = (validation.items ?? [])
    .filter((f) => f.message === 'conflictingContentTypes')
    .map((f) => f.details?.contentTypeId)
    .filter(Boolean);

  if (validation.items?.length) {
    log.warn('Validation findings:');
    for (const finding of validation.items) {
      console.log(`    ${finding.message}${finding.details?.message ? ` — ${finding.details.message}` : ''}`);
    }
    if (conflictingIds.length && !TAKEOVER_IDS.length) {
      console.log(
        `\n  These content types already exist in '${TARGET}' but aren't managed by this template.\n` +
          `  Re-run with --takeover ${conflictingIds.join(',')} to adopt them, once you've confirmed that's intended.\n`,
      );
    }
  } else {
    log.success('No validation findings.');
  }


  // A finding is resolved only if it is a conflict this run explicitly adopts. The gate used to
  // test `!(conflictingIds.length && TAKEOVER_IDS.length)`, which asked "is there at least one
  // conflict and at least one takeover?" rather than "is every finding accounted for" — so any
  // single --takeover opened the gate for every *other* finding too, including conflicts it
  // didn't name and findings of unrelated classes. `message` is an open string in the SDK's
  // types, so the set of classes isn't bounded by the one handled here.
  const takeoverSet = new Set(TAKEOVER_IDS);
  const unresolved = (validation.items ?? []).filter(
    (f) => !(f.message === 'conflictingContentTypes' && takeoverSet.has(f.details?.contentTypeId)),
  );

  const unknownTakeovers = TAKEOVER_IDS.filter((id) => !conflictingIds.includes(id));
  if (unknownTakeovers.length) {
    log.warn(
      `--takeover names ${unknownTakeovers.join(', ')}, which ${unknownTakeovers.length === 1 ? 'is' : 'are'} not in the conflict list — typo? Adopting nothing for ${unknownTakeovers.length === 1 ? 'it' : 'them'}.`,
    );
  }

  if (DRY_RUN) {
    // Reported after the unresolved set is computed, not before it. Previously dry-run returned
    // ahead of the gate and always printed "Would install", which made it useless as a pre-flight
    // for the one check it most needed to preview. Still exits 0 — a dry run reports, it doesn't
    // adjudicate.
    if (unresolved.length && !FORCE) {
      log.warn(
        `[dry-run] Would REFUSE to install into '${TARGET}' — ${unresolved.length} unresolved validation finding(s).`,
      );
    } else {
      log.info(`[dry-run] Would install template version ${template.sys.version} into '${TARGET}'.`);
    }
    return;
  }

  if (unresolved.length && !FORCE) {
    log.error(
      `Refusing to install into '${TARGET}' — ${unresolved.length} unresolved validation finding(s). Pass --force to override.`,
    );
    for (const finding of unresolved) {
      console.log(`    ${finding.message}${finding.details?.contentTypeId ? ` (${finding.details.contentTypeId})` : ''}`);
    }
    process.exit(1);
  }

  // Send only ids Contentful actually reported as conflicting. The warning above tells the
  // operator that unknown ids adopt nothing; this is what makes that true rather than merely
  // stated — otherwise a typo'd id is still POSTed as a ContentType link to adopt.
  const adoptableIds = TAKEOVER_IDS.filter((id) => conflictingIds.includes(id));
  const takeover = adoptableIds.length
    ? { items: adoptableIds.map((id) => ({ sys: { type: 'Link', linkType: 'ContentType', id } })) }
    : undefined;

  log.info(`Installing into '${TARGET}'...`);
  await client.environmentTemplate.install(
    { spaceId, environmentId: TARGET, environmentTemplateId: template.sys.id },
    { version: template.sys.version, deleteDeletedFields: DELETE_DELETED_FIELDS, takeover },
  );

  const result = await pollInstallation(client, {
    organizationId,
    spaceId,
    environmentId: TARGET,
    environmentTemplateId: template.sys.id,
  });

  if (result.sys.status === 'succeeded') {
    console.log(`\n  ✅  Installed template version ${template.sys.version} into '${TARGET}'.\n`);
  } else {
    log.error(`Installation into '${TARGET}' ended with status '${result.sys.status}'.`);
    if (result.sys.errors) console.error(JSON.stringify(result.sys.errors, null, 2));
    process.exit(1);
  }
}

main().catch((err) => {
  log.error(err.message ?? err);
  process.exit(1);
});

