import type { ContentfulClientApi } from 'contentful';
import Seo from '@salesforce/retail-react-app/app/components/seo';
import { Box, Spinner, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
import { ExperienceRoot, useFetchBySlug } from '@contentful/experiences-sdk-react';
import { StudioCanvasMode } from '@contentful/experiences-core/constants';
import { ContentfulLivePreviewProvider } from '@contentful/live-preview/react';
import { useServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { CONTENTFUL_FALLBACK_LOCALE, CONTENTFUL_LIVE_PREVIEW_ORIGIN } from '../../../config/contentful';
import { useContentfulClient } from '../../../hooks/useContentfulClient';

// Side-effect import — registers experience components with the Contentful Experiences SDK (cached, so this is fine)
import '../experiences/definitions';

/**
 * The single Contentful Experience Type covering every page on this site (per Contentful's own
 * Studio setup flow: one Experience Type per site/app, with every page — homepage, collection
 * pages, etc. — as its own entry distinguished by `slug`). The homepage entry uses slug
 * 'homepage' (Contentful doesn't allow an empty slug field) — see pages/home/index.tsx, mounted
 * at the exact `/` route. Note that `/homepage` (via the `/:slug` catch-all) resolves to the same
 * entry — a harmless alias, not a conflict.
 */
const EXPERIENCE_TYPE_ID = 'zimmermann';

type ExperienceFetchProps = {
  client: ContentfulClientApi<any>;
  slug: string;
  locale: string;
  isPreview: boolean;
};

/** Inner component so useFetchBySlug is always called unconditionally at the top level. */
const ExperienceFetch = ({ client, slug, locale, isPreview }: ExperienceFetchProps) => {
  const { experience, isLoading, error, mode } = useFetchBySlug({
    client: client as any,
    slug,
    experienceTypeId: EXPERIENCE_TYPE_ID,
    localeCode: locale,
  });

  // Inside Contentful Studio's Experience Builder canvas iframe, useFetchBySlug deliberately never
  // fetches or returns an `experience` — the real data is supplied to ExperienceRoot separately via
  // postMessage from Studio (@contentful/experiences-sdk-react's useFetchByBase, "supervised mode").
  // ExperienceRoot already branches on `mode` before ever looking at the `experience` prop, so it must
  // still be mounted here even when `experience` is undefined — bailing out to "Page not found" in this
  // case (as a plain `!experience` check would) prevents the canvas from ever rendering at all.
  const isSupervisedMode = mode === StudioCanvasMode.EDITOR || mode === StudioCanvasMode.READ_ONLY;

  if (isLoading) {
    return (
      <Box p={8} display="flex" justifyContent="center">
        <Spinner size="xl" />
      </Box>
    );
  }

  if (!isSupervisedMode && (error || !experience)) {
    // noindex so a missing/unresolved slug isn't indexed as valid content. NOTE: a true HTTP 404
    // isn't set here — useFetchBySlug resolves client-side (post-hydration), so `res` is unavailable
    // and SSR has already sent 200. A real 404 needs SSR prefetch (getProps) — tracked separately.
    return (
      <>
        <Seo noIndex />
        <Box p={8}>
          <Text color="red.500">Page not found.</Text>
        </Box>
      </>
    );
  }

  const root = <ExperienceRoot experience={experience} locale={locale} />;

  if (isPreview) {
    return (
      <>
        {/* noindex — preview mode serves draft content, must not be indexed */}
        <Seo noIndex />
        <ContentfulLivePreviewProvider
          locale={locale}
          enableInspectorMode={true}
          enableLiveUpdates={true}
          targetOrigin={CONTENTFUL_LIVE_PREVIEW_ORIGIN}
        >
          {root}
        </ContentfulLivePreviewProvider>
      </>
    );
  }

  return root;
};

export type ExperienceBySlugProps = {
  slug: string;
  isPreview?: boolean;
  isEditorCanvas?: boolean;
};

/**
 * Fetches and renders the `zimmermann` Experience entry matching `slug` (the single Experience
 * Type covering every page on this site). Shared by pages/experience/index.tsx (`/:slug`) and
 * pages/home/index.tsx (`/`, slug `''`) so both stay wired to the same experienceTypeId and the
 * same preview/Studio-canvas handling.
 */
export const ExperienceBySlug = ({ slug, isPreview = false, isEditorCanvas = false }: ExperienceBySlugProps) => {
  const { locale: siteLocale } = useMultiSite() as { locale?: { id: string } };
  const locale = siteLocale?.id || CONTENTFUL_FALLBACK_LOCALE;
  const { res } = useServerContext();
  // Preview requests use the CPA host+token only when a token is configured; otherwise the page
  // renders in normal delivery mode. A preview request WITHOUT a token is handled explicitly
  // below (404 + noindex) — it never silently falls back to delivery.
  const {
    client,
    previewUnavailable,
    isPreview: effectivePreview,
  } = useContentfulClient({
    preview: isPreview,
  });

  // @contentful/experiences-sdk-react's useFetchBySlug (called inside ExperienceFetch) branches its
  // initial canvas-mode state on `typeof window !== 'undefined'`, which differs between the SSR pass
  // and the client's first hydration pass when this page loads inside Contentful Studio's Experience
  // Builder canvas iframe — a structural hydration mismatch (React errors #418/#423) that discards the
  // whole render. Delaying ExperienceFetch's mount until after hydration means the server and the
  // client's first paint both render the same Spinner placeholder below, so there's nothing to
  // mismatch — useFetchBySlug then only ever runs in a pure client-side render pass.
  //
  // Only applied when `isEditorCanvas` (the `expEditorMode` query param Contentful Studio's canvas
  // appends to its iframe URL — visible server-side via the query string, unlike `window`/iframe
  // detection) is set — a normal storefront request never sets it, so it keeps rendering the real
  // experience content in the initial SSR response as before, per the perf budget in AGENTS.md.
  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    if (isEditorCanvas) {
      setMounted(true);
    }
  }, [isEditorCanvas]);

  // Preview requested but no CPA token (the non-prod gate): fail explicitly with a 404 and
  // noindex, mirroring the /preview route, so a `?preview` URL is never an indexable 200 on prod.
  if (previewUnavailable) {
    if (res) {
      res.status(404);
    }
    return (
      <>
        <Seo noIndex />
        <Box p={8}>
          <Text color="red.500">Preview is not enabled in this environment.</Text>
        </Box>
      </>
    );
  }

  if (!client) {
    // Contentful config missing = server misconfiguration, not a missing page: 500 (not 404),
    // + noindex so the error state is never indexed if it ever surfaces in production.
    if (res) {
      res.status(500);
    }
    return (
      <>
        <Seo noIndex />
        <Box p={8}>
          <Text color="red.500">Contentful configuration is missing — cannot render this page.</Text>
        </Box>
      </>
    );
  }

  if (isEditorCanvas && !mounted) {
    return (
      <Box p={8} display="flex" justifyContent="center">
        <Spinner size="xl" />
      </Box>
    );
  }

  return <ExperienceFetch client={client} slug={slug} locale={locale} isPreview={effectivePreview} />;
};

