import { useMemo } from 'react';
import { createClient } from 'contentful';
import type { ContentfulClientApi } from 'contentful';
import { getContentfulConfig, CONTENTFUL_PREVIEW_HOST, CONTENTFUL_DELIVERY_HOST } from '../config/contentful';

type UseContentfulClientOptions = {
  /** Request the Preview API (CPA) instead of the Delivery API (CDA). */
  preview?: boolean;
};

type UseContentfulClientResult = {
  /**
   * Memoised Contentful client, or `null` when required config (space/token) is missing.
   * The SDK's client generic is intentionally loose here — the Experiences SDK
   * (`useFetchBySlug`/`useFetchById`) accepts a broadly-typed client, matching the page components.
   */
  client: ContentfulClientApi<any> | null;
  /**
   * `true` when preview was requested but no CPA token is configured — the non-prod gate.
   * Callers MUST fail explicitly (HTTP 404 + `<Seo noIndex />`); they must never fall back to delivery.
   */
  previewUnavailable: boolean;
  /** `true` when the client is actually in preview mode (preview requested AND a CPA token is present). */
  isPreview: boolean;
};

/**
 * Builds a memoised Contentful Delivery/Preview client from environment config, centralising
 * the CPA-token gate so the `/preview` route and `?preview` Experience pages resolve the
 * preview-vs-delivery decision — and the "no token" behaviour — identically.
 *
 * @param options.preview whether to use the Preview API (CPA) host + token
 * @returns the memoised client (or `null` if unconfigured) plus preview-state flags for gating
 */
export const useContentfulClient = ({
  preview = false,
}: UseContentfulClientOptions = {}): UseContentfulClientResult => {
  // getContentfulConfig() reads getConfig() (pwa-kit-runtime SSR config), which is only
  // bootstrapped by the real dev/SSR/production app — Storybook's webpack build has no SSR
  // bootstrap, so getConfig() throws there. Treat that the same as "config missing" (client
  // stays null) rather than letting it crash every self-fetching component's story.
  const { spaceId, environment, previewAccessToken, accessToken } = ((): Partial<
    ReturnType<typeof getContentfulConfig>
  > => {
    try {
      return getContentfulConfig() ?? {};
    } catch {
      return {};
    }
  })();
  const previewUnavailable = preview && !previewAccessToken;
  const isPreview = preview && !!previewAccessToken;
  const token = isPreview ? previewAccessToken : accessToken;
  const host = isPreview ? CONTENTFUL_PREVIEW_HOST : CONTENTFUL_DELIVERY_HOST;

  const client = useMemo(() => {
    if (!spaceId || !token) return null;
    return createClient({ space: spaceId, environment, accessToken: token, host });
  }, [spaceId, environment, token, host]);

  return { client, previewUnavailable, isPreview };
};

import { useState, useEffect } from 'react';
import { getContentfulConfig } from '../config/contentful';
import type { ContentfulAsset } from '../types/contentful';

type ContentfulLink = {
  sys: {
    type: 'Link';
    linkType: 'Asset' | 'Entry';
    id: string;
  };
};

type ContentfulRawEntry = {
  sys: { id: string; [key: string]: unknown };
  fields: Record<string, ContentfulLink | ContentfulAsset | unknown>;
  [key: string]: unknown;
};

type ContentfulEntriesResponse = {
  items: ContentfulRawEntry[];
  includes?: {
    Asset?: ContentfulAsset[];
    Entry?: ContentfulRawEntry[];
  };
};

// Exported (alongside buildContentfulUrl/resolveLinkedAssets below) purely so they can be
// unit-tested directly as pure functions, the same way footer/index.tsx exports scopeToRegion —
// not part of this module's intended public surface for other callers.
//
// Throws rather than returning a nullable config so every caller's existing try/catch
// (which already converts a thrown Error into `error` state) handles the missing-config
// case for free, instead of each hook duplicating its own early-return branch.
export const getValidatedContentfulConfig = () => {
  const config = getContentfulConfig();
  if (!config.spaceId || !config.accessToken) {
    throw new Error('Contentful configuration missing');
  }
  return config;
};

export const buildContentfulUrl = (
  query: string,
  config: ReturnType<typeof getContentfulConfig>,
  preview: boolean,
  locale?: string,
  // include=2 is the minimum depth that resolves linked assets one level below a linked entry.
  // Pass 3 when a fetch chain is 3 hops deep (e.g. sizeGuide → sizeGuideTable → image → asset).
  include = 2,
): string => {
  const { spaceId, accessToken, previewAccessToken, environment } = config;
  const baseUrl = preview ? 'https://preview.contentful.com' : 'https://cdn.contentful.com';
  const token = preview ? previewAccessToken : accessToken;
  const localeParam = locale ? `&locale=${encodeURIComponent(locale)}` : '';
  return `${baseUrl}/spaces/${spaceId}/environments/${environment}/entries?${query}&access_token=${token}&include=${include}${localeParam}`;
};

export const resolveLinkedAssets = <T extends ContentfulRawEntry>(
  item: T,
  includes?: ContentfulEntriesResponse['includes'],
  visitedIds: Set<string> = new Set(),
): T => {
  // Guard against cyclic entry graphs (A → B → A). Contentful's include=2 limit controls
  // response depth but does not prevent cycles in the returned data.
  if (visitedIds.has(item.sys.id)) return item;
  const nextVisited = new Set(visitedIds).add(item.sys.id);

  // Clone fields too, not just the top-level item — a shallow `{ ...item }` still shares the
  // same `fields` object reference with the original, so writing into resolvedItem.fields
  // below would otherwise mutate the raw Contentful response entry in place.
  const resolvedItem = { ...item, fields: { ...item.fields } };
  if (item.fields) {
    Object.keys(item.fields).forEach((fieldKey) => {
      const fieldValue = item.fields[fieldKey] as ContentfulLink;
      if (fieldValue?.sys?.type === 'Link') {
        if (fieldValue.sys.linkType === 'Asset') {
          const linked = includes?.Asset?.find((asset) => asset.sys.id === fieldValue.sys.id);
          if (linked) resolvedItem.fields[fieldKey] = linked;
        } else if (fieldValue.sys.linkType === 'Entry') {
          const linked = includes?.Entry?.find((entry) => entry.sys.id === fieldValue.sys.id);
          if (linked && !nextVisited.has(linked.sys.id)) {
            resolvedItem.fields[fieldKey] = resolveLinkedAssets(linked, includes, nextVisited);
          } else {
            // Delete for both unresolved links and cyclic entries — a cyclic entry returning
            // its own stub (the pre-cycle-check fallback) is as unsafe as an unresolved link.
            delete resolvedItem.fields[fieldKey];
          }
        }
      } else if (Array.isArray(fieldValue)) {
        // Resolve arrays of links (e.g. an `items` field holding multiple linked entries/assets).
        // Unresolved and cyclic Entry links are filtered out rather than returned as Link stubs —
        // a stub passing through the T[] cast is invisible to TypeScript but throws at runtime.
        resolvedItem.fields[fieldKey] = fieldValue
          .map((element) => {
            const el = element as ContentfulLink;
            if (el?.sys?.type === 'Link') {
              if (el.sys.linkType === 'Asset') {
                const linked = includes?.Asset?.find((asset) => asset.sys.id === el.sys.id);
                return linked ?? element;
              } else if (el.sys.linkType === 'Entry') {
                const linked = includes?.Entry?.find((entry) => entry.sys.id === el.sys.id);
                if (linked && !nextVisited.has(linked.sys.id)) {
                  return resolveLinkedAssets(linked, includes, nextVisited);
                }
                return null;
              }
            }
            return element;
          })
          .filter((el) => el !== null) as typeof fieldValue;
      }
    });
  }
  return resolvedItem;
};

/**
 * Fetches a single Contentful entry by its sys.id and resolves linked assets/entries.
 *
 * @param entryId - Contentful entry sys.id to fetch.
 * @param preview - When true, uses the Preview API (draft content). Defaults to false.
 * @param locale - Optional locale string (e.g. 'en-AU'). Omit to use Contentful's default.
 * @returns `{ data, isLoading, error }` where `data` is typed as `T | null`.
 */
export const useContentfulEntry = <T>(entryId: string, preview = false, locale?: string) => {
  const [data, setData] = useState<T | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    const controller = new AbortController();

    // Reset rather than leaving the previous request's data/error in place — without this,
    // a locale change on an already-mounted consumer (e.g. UiCopyProvider) would keep
    // rendering the old locale's content until the new fetch resolves.
    setIsLoading(true);
    setError(null);
    setData(null);

    const fetchEntry = async () => {
      try {
        const config = getValidatedContentfulConfig();
        // Search endpoint with sys.id, so include=2 still resolves linked assets.
        const url = buildContentfulUrl(`sys.id=${entryId}`, config, preview, locale);
        const response = await fetch(url, { signal: controller.signal });

        if (!response.ok) {
          throw new Error(`Contentful API error: ${response.status}`);
        }

        const result: ContentfulEntriesResponse = await response.json();
        const item = result.items[0];
        if (!item) {
          throw new Error(`Entry ${entryId} not found`);
        }
        setData(resolveLinkedAssets(item, result.includes) as T);
      } catch (err) {
        if (err instanceof DOMException && err.name === 'AbortError') return;
        setError(err instanceof Error ? err : new Error('Unknown error'));
      } finally {
        // Guards against the superseded request's own `finally` running after this effect
        // has already started a new one (e.g. deps changed before the prior fetch settled) —
        // controller.signal.aborted flips synchronously the instant cleanup calls abort(),
        // so by the time an aborted request's finally runs, it can tell it's no longer current.
        if (!controller.signal.aborted) setIsLoading(false);
      }
    };

    void fetchEntry();
    return () => controller.abort();
  }, [entryId, preview, locale]);

  return { data, isLoading, error };
};

/**
 * Fetches all Contentful entries of a given content type and resolves their linked assets/entries.
 *
 * @param contentType - Contentful content type ID (e.g. 'iconAndText').
 * @param preview - When true, uses the Preview API (draft content). Defaults to false.
 * @param locale - Optional locale string (e.g. 'en-AU'). Omit to use Contentful's default.
 * @param filter - Optional additional Contentful query filter appended to the request
 *   (e.g. `'fields.placement=benefits'`). Follows Contentful's Search Parameters syntax.
 * @param enabled - When false, skips the fetch entirely (useful for conditional fetching).
 * @returns `{ data, isLoading, error }` where `data` is typed as `T[] | null`.
 */
export const useContentfulEntries = <T>(
  contentType: string,
  preview = false,
  locale?: string,
  filter?: string,
  enabled = true,
  include = 2,
) => {
  const [data, setData] = useState<T[] | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    if (!enabled) {
      setData(null);
      setError(null);
      setIsLoading(false);
      return;
    }

    const controller = new AbortController();

    // Reset rather than leaving the previous request's data/error in place — without this,
    // a locale change on an already-mounted consumer (e.g. UiCopyProvider) would keep
    // rendering the old locale's content until the new fetch resolves.
    setIsLoading(true);
    setError(null);
    setData(null);

    const fetchEntries = async () => {
      try {
        const config = getValidatedContentfulConfig();
        const query = filter ? `content_type=${contentType}&${filter}` : `content_type=${contentType}`;
        const url = buildContentfulUrl(query, config, preview, locale, include);
        const response = await fetch(url, { signal: controller.signal });

        if (!response.ok) {
          throw new Error(`Contentful API error: ${response.status}`);
        }

        const result: ContentfulEntriesResponse = await response.json();
        const resolvedItems = result.items.map((item) => resolveLinkedAssets(item, result.includes));
        setData(resolvedItems as T[]);
      } catch (err) {
        if (err instanceof DOMException && err.name === 'AbortError') return;
        setError(err instanceof Error ? err : new Error('Unknown error'));
      } finally {
        // See useContentfulEntry's identical guard above for why this check is needed.
        if (!controller.signal.aborted) setIsLoading(false);
      }
    };

    void fetchEntries();
    return () => controller.abort();
  }, [contentType, preview, locale, filter, enabled, include]);

  return { data, isLoading, error };
};

