import React from 'react';
import { useLocation } from 'react-router-dom';
import { ExperienceBySlug } from '../../components/contentful/experienceBySlug';

type ExperienceProps = {
  /** Slug already normalised by the caller (site/locale prefix removed); derived from the pathname otherwise. */
  slug?: string;
};

const Experience = ({ slug: slugProp }: ExperienceProps = {}) => {
  const { pathname, search } = useLocation();
  const slug = slugProp ?? pathname.slice(1); // strip leading '/'
  const params = new URLSearchParams(search);
  const isPreview = params.has('preview');
  // Contentful Studio's Experience Builder canvas appends this to its iframe URL — see the
  // hydration-workaround comment in ExperienceBySlug for why this needs to be visible server-side.
  const isEditorCanvas = params.has('expEditorMode');

  return <ExperienceBySlug slug={slug} isPreview={isPreview} isEditorCanvas={isEditorCanvas} />;
};

Experience.getTemplateName = () => 'experience';

export default Experience;

